#!/usr/bin/env node
// Mechanically derives prisma/schema.sqlite.prisma from the canonical
// prisma/schema.prisma so local development gets a zero-setup SQLite DB
// without maintaining two hand-written schemas. Prisma requires the
// datasource `provider` to be a static literal per generated client (it
// cannot be swapped via env var), so this is the pragmatic way to keep one
// authored source of truth while still generating a SQLite-flavored client.
//
// Do NOT hand-edit prisma/schema.sqlite.prisma — it is regenerated by
// `npm run dev` / `npm run prisma:generate:sqlite` every time.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const canonicalPath = path.join(__dirname, '..', 'prisma', 'schema.prisma');
const sqlitePath = path.join(__dirname, '..', 'prisma', 'schema.sqlite.prisma');

const canonical = readFileSync(canonicalPath, 'utf8');

// Deliberately keeps the same generator `output` (the default @prisma/client
// location) as the canonical schema — whichever schema was generated most
// recently (sqlite in dev, postgresql in the prod build) is what
// `import { PrismaClient } from '@prisma/client'` resolves to. This avoids
// application code needing to branch its import path by environment.
const sqliteSchema = canonical
  .replace(
    /datasource db \{\s*provider = "postgresql"\s*url\s*=\s*env\("DATABASE_URL"\)\s*\}/,
    'datasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}',
  )
  .replace(
    '// ============================================================================\n// Canonical Prisma schema — source of truth, targets PostgreSQL (production).',
    '// ============================================================================\n// AUTO-GENERATED from schema.prisma by scripts/generate-sqlite-schema.mjs.\n// Do not edit by hand — edit schema.prisma instead and re-run `npm run dev`.',
  );

if (sqliteSchema === canonical) {
  console.error(
    'generate-sqlite-schema: pattern replacement did not match — schema.prisma may have drifted from the expected shape.',
  );
  process.exit(1);
}

writeFileSync(sqlitePath, sqliteSchema);
console.log(`Generated ${path.relative(process.cwd(), sqlitePath)} from schema.prisma`);
